def transform(g):
 from collections import Counter, deque
 R,C=len(g),len(g[0]); bg=Counter(x for row in g for x in row).most_common(1)[0][0]
 out=[[bg]*C for _ in range(R)]; seen=set()
 for r in range(R):
  for c in range(C):
   v=g[r][c]
   if v==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=nx<R and 0<=ny<C and (nx,ny) not in seen and g[nx][ny]==v:
      seen.add((nx,ny));q.append((nx,ny))
   if len(cells)>=3:
    a=min(x for x,y in cells); b=max(x for x,y in cells); l=min(y for x,y in cells); rr=max(y for x,y in cells)
    for x in range(a,b+1):
     for y in range(l,rr+1): out[x][y]=v
 return out
